"""隔离 Chromium 交互回归；只使用合成内容，不操作用户桌面或剪贴板。"""
import argparse,json,time
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
(ROOT/'previews').mkdir(parents=True,exist_ok=True)
PARSER=argparse.ArgumentParser();PARSER.add_argument('--group',choices=['core','tasks','system','files'],default='core');args=PARSER.parse_args()
results=[];errors=[];requests=[]
def check(name,value,detail=None):
    entry={'name':name,'pass':bool(value)}
    if detail is not None:entry['detail']=detail
    results.append(entry);print(('PASS ' if value else 'FAIL ')+name,flush=True)
def wait(ms=200):page.wait_for_timeout(ms)
def state(expr):return page.evaluate('('+expr+')')
def click(action):page.locator('.tool[data-action="'+action+'"]').click()
def reset():page.evaluate('demo.reset()');wait(650)
def rect_box():return page.locator('#capture').bounding_box()
def draw(kind='rect'):
    click(kind);r=rect_box();page.mouse.move(r['x']+r['width']*.19,r['y']+r['height']*.30);page.mouse.down();page.mouse.move(r['x']+r['width']*.44,r['y']+r['height']*.55,steps=10);page.mouse.up();wait(500)
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
    context=browser.new_context(viewport={'width':1600,'height':1080},accept_downloads=True)
    page=context.new_page();page.set_default_timeout(7000);page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url))
    page.set_content((ROOT/'Screenshot-Liquid-v2.html').read_text(encoding='utf-8'),wait_until='load');wait(800)
    check('启动无脚本异常',state('!!window.demo') and not errors)
    if args.group=='core':
        b=page.locator('.tool[data-action=rect]');before=b.bounding_box();page.mouse.move(before['x']+before['width']-5,before['y']+5);wait(400)
        after=b.bounding_box();skin=b.locator('.skin').evaluate('(e)=>getComputedStyle(e).transform')
        check('临近形变不改变命中盒',before==after)
        check('按钮表面实际产生形变',skin!='none' and skin!='matrix(1, 0, 0, 1, 0, 0)',skin)
        neighbor=page.locator('.tool[data-action=arrow] .skin').evaluate('(e)=>getComputedStyle(e).transform')
        check('相邻按钮有传导',neighbor!='none' and neighbor!='matrix(1, 0, 0, 1, 0, 0)',neighbor)
        check('悬停不切换工具',state('demo.state.tool==="select"'))
        a=page.locator('.tool[data-action=arrow]').bounding_box();page.mouse.move(a['x']+a['width']/2,a['y']+a['height']/2,steps=8);wait(50)
        check('同组跨越生成短暂液桥',bool(page.locator('#liquidBridge').get_attribute('d')))
        wait(400);check('稳定悬停后液桥消失',not page.locator('#liquidBridge').get_attribute('d'))
        page.mouse.move(10,10);wait(1300);frames=state('Liquid.E.frames');wait(300);check('停止交互后动画调度休眠',state('Liquid.E.frames')==frames)
        reset();r=rect_box();page.mouse.move(r['x']+r['width'],r['y']+r['height']);page.mouse.down();page.mouse.move(r['x']+r['width']+26,r['y']+r['height']+18,steps=5);wait(30)
        cue=page.locator('#sizeTag').evaluate('(e)=>({inline:e.style.transform,computed:getComputedStyle(e).transform})')
        check('手柄拖动的尺寸胶囊有合法位移',cue['inline'].startswith('translate(') and 'NaN' not in cue['inline'] and 'undefined' not in cue['inline'],cue)
        page.keyboard.press('Escape');page.mouse.up();wait(350)
        check('尺寸胶囊回流到稳定位置',page.locator('#sizeTag').evaluate('(e)=>{const m=new DOMMatrix(getComputedStyle(e).transform);return Math.abs(m.m41)<0.2&&Math.abs(m.m42)<0.2}'))
        reset()
        draw();check('手绘矩形只提交一次',state('demo.state.marks.length===1 && demo.state.hi===1'))
        old=state('JSON.parse(JSON.stringify(demo.state.marks[0]))');page.evaluate('demo.closePanel(false)');wait(220)
        r=rect_box();page.mouse.move(r['x']+old['x']/state('demo.state.docW')*r['width'],r['y']+(old['y']+10)/state('demo.state.docH')*r['height']);page.mouse.down();page.mouse.move(r['x']+r['width']+120,r['y']+r['height']*.55,steps=12);page.mouse.up();wait(300)
        new=state('demo.state.marks[0]');check('整体拖到边界不压缩标注',abs((old['x2']-old['x'])-(new['x2']-new['x']))<.01)
        page.evaluate('demo.history(-1)');wait(100);check('拖动撤销恢复原坐标',abs(state('demo.state.marks[0].x')-old['x'])<.01)
        reset();click('text');r=rect_box();page.mouse.click(r['x']+100,r['y']+100);page.locator('#annotationInput').fill('');page.keyboard.press('Escape');check('取消空文字无对象无历史',state('demo.state.marks.length===0 && demo.state.hi===0'))
        page.mouse.click(r['x']+120,r['y']+120);page.locator('#annotationInput').fill('液态共生');page.keyboard.press('Enter');wait(500);check('文字明确提交后可编辑',state('demo.state.marks[0]?.text==="液态共生"'))
        reset();click('rect');r=rect_box();page.mouse.move(r['x']+60,r['y']+80);page.mouse.down();page.mouse.move(r['x']+160,r['y']+170);page.keyboard.press('Escape');page.mouse.up();check('绘制中 Esc 不产生半成品',state('demo.state.marks.length===0 && !demo.state.gesture'))
        reset();click('beauty');wait(600);page.locator('[data-preset=linen]').click();wait(150);check('预设实际改变图片与输出尺寸',state('demo.state.style.pad===32 && demo.exportCanvas().width===demo.state.docW+64'))
        page.locator('[data-color=background]').click();page.locator('#colorHex').fill('#123456');page.keyboard.press('Escape');check('颜色取消不污染文档',state('demo.state.style.bg!=="#123456"'))
        page.locator('[data-color=background]').click();page.locator('#colorHex').fill('#123456');page.locator('#colorApply').click();wait(150);check('颜色确认后写入文档',state('demo.state.style.bg==="#123456"'))
        page.locator('summary',has_text='边框与自定义预设').click();page.locator('#presetName').fill('测试预设');page.locator('#savePreset').click();wait(150);check('保存预设不是假提示',state('demo.state.presets.some(p=>p.name==="测试预设")'))
        page.evaluate('demo.openPanel("ocr");demo.openPanel("more");demo.openPanel("beauty");');wait(900)
        check('快速切换无消失或残影',state('demo.state.panel==="beauty" && !document.querySelector("#panel").hidden && document.querySelector("#morph").hidden'))
        check('属性卡不遮住完成按钮',state('(()=>{const a=demo.geometry.panel,b=demo.geometry.rail;return Math.min(a.x+a.w,b.x+b.w)<=Math.max(a.x,b.x)||Math.min(a.y+a.h,b.y+b.h)<=Math.max(a.y,b.y)})()'))
    if args.group=='tasks':
        page.evaluate('document.querySelector("#outcome").value="failure"');click('done');wait(700)
        check('复制失败保留原图与编辑',state('!!demo.state.image && demo.state.phase==="editing"'))
        page.evaluate('document.querySelector("#outcome").value="stale"');click('done');wait(700)
        check('过期确认不退出',state('demo.state.phase==="editing" && !!demo.state.image'))
        page.evaluate('document.querySelector("#outcome").value="slow"');click('done');wait(100);page.locator('#cancelTask').click();wait(100)
        check('慢任务可以取消',state('!demo.state.task && demo.state.phase==="editing"'))
        page.evaluate('document.querySelector("#outcome").value="success"');click('ocr');wait(600);page.locator('#runOcr').click();wait(1400)
        check('识别结果可校对',state('demo.state.sourceText.includes("The art")'))
        page.locator('#runTranslation').click();wait(1400);check('翻译独立保留原文',state('demo.state.sourceText.includes("The art") && demo.state.translatedText.includes("日常")'))
        page.locator('#sourceText').fill('new source');wait(80);check('原文修改提示译文过期',page.locator('#translationStale').inner_text().find('已变化')>=0)
        page.evaluate('demo.closePanel(false)');wait(220);page.evaluate('document.querySelector("#outcome").value="empty"');prev=state('demo.state.sourceText');page.evaluate('demo.runOcr()');wait(1400);check('空结果不覆盖旧内容',state('demo.state.sourceText')==prev)
        page.evaluate('document.querySelector("#outcome").value="success"');click('translate');wait(1450)
        check('原位译文为独立图层',state('demo.state.imageTranslated && demo.state.translationBlocks.length===2'))
        page.evaluate('demo.history(-1)');check('原位翻译单步撤销',state('!demo.state.imageTranslated'))
        page.evaluate('demo.history(1)');click('reader');wait(250);page.locator('#compareText').click();page.locator('#fontUp').click();check('原译对照与字号可操作',state('demo.state.compare && demo.state.readerFont===20'))
        box=page.locator('#reader').bounding_box();h=page.locator('#reader header').bounding_box();page.mouse.move(h['x']+90,h['y']+15);page.mouse.down();page.mouse.move(h['x']+130,h['y']+45,steps=5);page.mouse.up();wait(100);moved=page.locator('#reader').bounding_box();page.locator('#readerClose').click();click('reader');wait(200)
        check('阅读窗重开保持手动位置',abs(page.locator('#reader').bounding_box()['x']-moved['x'])<1)
        page.locator('#readerClose').click();page.evaluate('document.querySelector("#outcome").value="slow"');click('translate');wait(100);page.locator('#newCapture').click();wait(4500)
        check('新捕获使迟到任务失效',state('demo.state.phase==="capturing" && !demo.state.task'))
        page.keyboard.press('Escape');wait(500);check('取消新捕获恢复旧编辑',state('demo.state.phase==="editing" && !!demo.state.image'))
        page.evaluate('document.querySelector("#outcome").value="success"');click('done');wait(470);page.locator('#newCapture').click();wait(650)
        check('退出动画可被新捕获打断',state('demo.state.phase==="capturing" && !document.querySelector(".exit-ghost")'))
        page.keyboard.press('Escape');wait(450);click('done');wait(1000)
        check('确认后才退出并清空会话',state('demo.state.phase==="hidden" && !demo.state.image && demo.state.marks.length===0'))
        page.locator('#newCapture').click();page.keyboard.press('Escape');wait(100)
        check('无文档时取消捕获不恢复旧图',state('demo.state.phase==="hidden" && !demo.state.image'))
    if args.group=='system':
        page.evaluate('demo.openSettings("capture")');wait(250);page.locator('#settingHotkey').fill('Ctrl + Alt + B');page.locator('[data-settings=services]').click();page.locator('[data-settings=capture]').click();check('设置切页不丢失输入草稿',page.locator('#settingHotkey').input_value()=='Ctrl + Alt + B')
        page.locator('#settingHotkey').fill('???');page.locator('#applySettings').click();check('错误提示在当前模态内可见',page.locator('.inline-feedback').is_visible())
        page.locator('[data-settings=services]').click();page.locator('#addService').click();check('添加服务产生真实条目',state('demo.state.services.length===2'))
        page.locator('[data-settings=updates]').click();page.locator('#downloadUpdate').click();wait(250);page.locator('#cancelSystem').click();check('模拟下载取消保留状态', '取消' in page.locator('#updateMessage').inner_text())
        page.keyboard.press('Escape');check('关闭模态归还主界面交互',not state('document.querySelector("#app").inert'))
        page.evaluate('demo.openComponents()');wait(250);page.locator('#componentTerms').click();check('未同意不能继续',page.locator('#termsAccept').is_disabled());page.locator('#termsAgree').check();check('明确勾选后可继续',page.locator('#termsAccept').is_enabled());page.locator('#termsDecline').click();
        page.evaluate('document.querySelector("#reduced").checked=true;document.querySelector("#reduced").dispatchEvent(new Event("change"));');click('beauty');wait(200);check('减少动态无遗留形变层',state('document.querySelector("#morph").hidden && Liquid.reduced()'))
        page.emulate_media(reduced_motion='reduce');page.evaluate('document.querySelector("#reduced").checked=false;document.querySelector("#reduced").dispatchEvent(new Event("change"));');check('系统减少动态不能被应用覆盖',state('Liquid.reduced()'))
        page.emulate_media(reduced_motion='no-preference');page.evaluate('document.querySelector("#reduced").dispatchEvent(new Event("change"));');
        for width in [1024,720,390]:
            page.set_viewport_size({'width':width,'height':900});wait(400);page.evaluate('demo.reset()');wait(700);click('beauty');wait(650)
            check(f'{width}px 页面无横向溢出',state('document.documentElement.scrollWidth<=innerWidth'))
            check(f'{width}px 完成按钮在舞台内',state('(()=>{const a=document.querySelector(".tool[data-action=done]").getBoundingClientRect(),s=document.querySelector("#stage").getBoundingClientRect();return a.left>=s.left&&a.right<=s.right&&a.bottom<=s.bottom})()'))
            check(f'{width}px 面板不覆盖工具轨',state('(()=>{const a=demo.geometry.panel,b=demo.geometry.rail;return Math.min(a.x+a.w,b.x+b.w)<=Math.max(a.x,b.x)||Math.min(a.y+a.h,b.y+b.h)<=Math.max(a.y,b.y)})()'))
            page.screenshot(path=str(ROOT/f'previews/responsive-{width}.png'),full_page=True)
        page.evaluate('demo.openReader(true)');wait(200);check('窄屏阅读隔离后层操作',state('document.querySelector("#rail").inert'))
        page.locator('#readerClose').click();check('关闭阅读恢复后层操作',not state('document.querySelector("#rail").inert'))
    if args.group=='files':
        reset();draw('cover');page.evaluate('demo.closePanel(false)');wait(220)
        check('实色遮盖导出不透明',state('(()=>{const m=demo.state.marks[0],c=demo.exportCanvas(),d=c.getContext("2d").getImageData((m.x+m.x2)/2,(m.y+m.y2)/2,1,1).data;return d[0]===48&&d[1]===51&&d[2]===46&&d[3]===255})()'))
        with page.expect_download() as event:
            page.locator('#exportPng').click()
        event.value.save_as(str(ROOT/'tests/export-sample.png'))
        check('PNG 可实际下载', (ROOT/'tests/export-sample.png').stat().st_size>100)
        page.evaluate('demo.openPanel("more")');wait(650)
        with page.expect_download() as event: page.locator('[data-menu=save-project]').click()
        project=ROOT/'tests/roundtrip.liquid.json';event.value.save_as(str(project));payload=json.loads(project.read_text(encoding='utf-8'))
        check('项目保存包含图片像素',payload.get('imageData','').startswith('data:image/png;base64,'))
        reset();page.locator('#projectFile').set_input_files(str(project));wait(800)
        check('演示项目往返保留标注',state('demo.state.marks.length===1 && demo.state.marks[0].type==="cover"'))
        import base64,io
        from PIL import Image
        expected_size=Image.open(io.BytesIO(base64.b64decode(payload['imageData'].split(',')[1]))).size
        check('项目往返保留真实图片尺寸',(state('demo.state.docW'),state('demo.state.docH'))==expected_size)
        bad=ROOT/'tests/invalid.json';bad.write_text('{"format":"wrong"}')
        before=state('demo.state.docId');page.locator('#projectFile').set_input_files(str(bad));wait(300)
        check('无效项目保留旧文档',state('demo.state.docId')==before and state('demo.state.marks.length')==1)
        from PIL import Image
        fixture=ROOT/'tests/synthetic.png';Image.new('RGB',(640,360),(20,180,100)).save(fixture)
        page.locator('#imageFile').set_input_files(str(fixture));wait(800)
        check('本机图片导入保持原尺寸',state('demo.state.docW===640 && demo.state.docH===360'))
        check('导入图片未被样例画面替换',state('(()=>{const d=demo.exportCanvas().getContext("2d").getImageData(100,100,1,1).data;return d[0]===20&&d[1]===180&&d[2]===100})()'))
        click('select');r=rect_box();before=state('({...demo.state.r})');handle=page.locator('.handle[data-dir=s]').bounding_box();page.mouse.move(handle['x']+handle['width']/2,handle['y']+handle['height']/2);page.mouse.down();page.mouse.move(handle['x']+handle['width']/2,handle['y']+handle['height']/2+24,steps=5);page.mouse.up();wait(250)
        after=state('({...demo.state.r})')
        check('导入图片上下手柄实际调整显示尺寸',after['h']>before['h']+10 and abs(after['w']/after['h']-640/360)<0.001)
        check('导入图片显示调整不改变输出像素',state('demo.exportCanvas().width===640 && demo.exportCanvas().height===360'))
        check('2× PNG 重新按目标尺寸绘制',state('demo.exportCanvas(2).width===1280 && demo.exportCanvas(2).height===720'))

        check('拒绝越界或未知标注类型',state('(()=>{try{demo.validateProject({format:"screenshot-liquid-design",version:2,marks:[{type:"script"}]},640,360);return false}catch{return true}})()'))
    check('本组无脚本异常',not errors,errors)
    check('本组无外部网络请求',not any(u.startswith(('http://','https://')) for u in requests),requests)
    data={'group':args.group,'passed':sum(r['pass'] for r in results),'total':len(results),'results':results,'browser':'isolated Chromium / Linux','source':'synthetic local prototype','errors':errors}
    (ROOT/f'tests/results-{args.group}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'group':args.group,'passed':data['passed'],'total':data['total']},ensure_ascii=False))
    browser.close()
    if not all(r['pass'] for r in results):raise SystemExit(1)
